package jp.personal.hanshinedge.prospective;
import android.content.Context;import androidx.work.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class BackgroundScheduler {
 public static final String TAG="JRA_EDGE_MONITOR";
 public static void schedule(Context c,String prefix,JSONObject reg)throws Exception{if(!reg.optBoolean("REAL_PROSPECTIVE"))return;long post=ProspectiveRuntime.stamp(reg.getString("scheduled_post_time"));for(int i=0;i<5;i++){String stage=i<4?ProspectiveRuntime.STAGE[i]:"RESULT";long at=i<4?post-ProspectiveRuntime.TARGET[i]*1000L:post+180000;Data input=new Data.Builder().putString("prefix",prefix).putString("race_id",reg.getString("race_id")).putString("stage",stage).build();OneTimeWorkRequest task=new OneTimeWorkRequest.Builder(RuntimeWorker.class).setInputData(input).setInitialDelay(Math.max(0,at-System.currentTimeMillis()),TimeUnit.MILLISECONDS).setConstraints(new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()).setBackoffCriteria(BackoffPolicy.LINEAR,30,TimeUnit.SECONDS).addTag(TAG).addTag("PREFIX:"+prefix).addTag("RACE:"+reg.getString("race_id")).build();WorkManager.getInstance(c).enqueueUniqueWork(prefix+":"+reg.getString("race_id")+":"+stage,ExistingWorkPolicy.KEEP,task);}}
 public static void resume(Context c,String prefix)throws Exception{try(ProspectiveRuntime r=new ProspectiveRuntime(c,prefix)){JSONArray regs=r.registrations();for(int i=0;i<regs.length();i++)schedule(c,prefix,regs.getJSONObject(i));}}
 public static void recordRun(Context c,String prefix,String error){c.getSharedPreferences(prefix+"-worker-status",0).edit().putLong("last_run",System.currentTimeMillis()).putString("last_error",error==null?"":error).apply();}
 public static JSONObject status(Context c)throws Exception{JSONObject p=new JSONObject().put("state","UNVERIFIED").put("last_run",c.getSharedPreferences("jra-ui-worker-status",0).getLong("last_run",0)).put("last_error",c.getSharedPreferences("jra-ui-worker-status",0).getString("last_error",""));java.util.List<WorkInfo> info;try{info=WorkManager.getInstance(c).getWorkInfosByTag(TAG).get(2,TimeUnit.SECONDS);}catch(Exception e){return p.put("race_count",JSONObject.NULL).put("next_check_ms",JSONObject.NULL).put("status_error","WORKMANAGER_STATUS_UNAVAILABLE");}int active=0;long next=Long.MAX_VALUE;Set<String> races=new HashSet<>();for(WorkInfo w:info)if(w.getTags().contains("PREFIX:jra-ui")&&!w.getState().isFinished()){active++;next=Math.min(next,w.getNextScheduleTimeMillis());for(String t:w.getTags())if(t.startsWith("RACE:"))races.add(t.substring(5));}p.put("race_count",races.size()).put("next_check_ms",next==Long.MAX_VALUE?JSONObject.NULL:next);return p.put("state",active>0?"ACTIVE":"STOPPED").put("work_count",active).put("timing_policy","BEST_EFFORT_FIXED_WINDOWS_NO_FORCE_STOP_SURVIVAL");}
}
